import { getHostEndpoint } from '../utils/_endpoint';
/**
 * Navigates users to specific Dashboard page defined by a route descriptor
 * without triggering a full-page reload.
 *
 * @public
 * @see https://docs.stripe.com/stripe-apps/route-descriptors
 */
export function navigateToDashboardRoute(descriptor) {
    return getHostEndpoint().call.navigateToDashboardRoute?.(descriptor);
}
